KG_CODE("f:tests/test_db1_controller.py","\"\"\"db1 (owner order 2026-10-30): the dashboard as controller and recorder.\n\nCUA at 815dfd96 records a trajectory per session (turn-NNNNN/action.json: tool, arguments, result_summary,\nresult_error, timestamp; recording.rs:1435-1458) and replays it in turn order through the same dispatch path with\ndelay_ms and stop_on_error (recording_tools.rs:333-470). Here the daemon records every run by itself, redacts the\narguments, keeps a ref's identity for the replay, and the owner's buttons reach the agent (owner_controls).\n\"\"\"\nfrom __future__ import annotations\n\nimport json\nimport os\nimport subprocess\nimport sys\nimport tempfile\nimport time\nimport unittest\nfrom pathlib import Path\nfrom unittest.mock import patch\n\nfrom autoskill import trajectory\nfrom autoskill.daemon import Daemon\nfrom autoskill.protocol import ErrorCode, ProtocolError, Request\nfrom autoskill.safety.permissions import PermissionMode, PermissionPolicy, save_policy\n\n\ndef _turn(n, tool, arguments=None, *, read_only=False, target=None):\n    return {\"turn\": n, \"tool\": tool, \"arguments\": arguments or {}, \"read_only\": read_only, \"target\": target,\n            \"outcome\": \"ok\"}\n\n\n\nclass ReplayRuleRowTests(unittest.TestCase):\n    \"\"\"fix-r1 T9 (D-4, F9): a step a program-specific replay rule changed or added names that rule on its row.\"\"\"\n\n    def play(self, turns, *, text=\"\", windows=(), act=None):\n        calls = []\n\n        def delegate(method, params):\n            calls.append((method, dict(params)))\n            if method == \"desktop.observe\":\n                return {\"text\": text(params) if callable(text) else text}\n            if method == \"desktop.windows\":\n                return {\"windows\": list(windows)}\n            if act is not None:\n                return act(method, params)\n            return {\"effect_state\": \"committed\"}\n        out = trajectory.replay(delegate, turns, delay_ms=0, sleep=lambda s: None)\n        return out, calls\n\n    def rules_of(self, row):\n        return row.get(\"rules\") or []\n\n    def test_r_a_search_window(self):\n        turn = _turn(1, \"desktop.key\", {\"window\": \"#5\", \"keys\": \"a\"}, target={\"window\": {\"window_title\": \"Search\"}})\n        out, _ = self.play([turn], windows=[{\"handle\": 7, \"title\": \"Search\"}])\n        self.assertIn(\"R-a Search window\", self.rules_of(out[\"turns\"][0]))\n\n    def test_r_b_grid_cell_real_click(self):\n        turn = _turn(1, \"desktop.click\", {\"ref\": \"@e1\"},\n                     target={\"ref\": {\"ref\": \"@e1\", \"role\": \"griditem\", \"name\": \"C2\", \"window_title\": \"Book1 - Excel\"}})\n        out, _ = self.play([turn], text='@e80 griditem \"C2\" [id=C2]')\n        self.assertEqual(self.rules_of(out[\"turns\"][0]), [\"R-b grid cell real click\"])\n\n    def test_r_c_menu_gallery_expand(self):\n        turn = _turn(1, \"desktop.click\", {\"ref\": \"@e8\"},\n                     target={\"ref\": {\"ref\": \"@e8\", \"role\": \"menuitem\", \"name\": \"Illustrations\",\n                                     \"window_title\": \"Book1 - Excel\", \"class_name\": \"NetUIAnchor\"}})\n        out, _ = self.play([turn], text='@e51 menuitem \"Illustrations\"')\n        self.assertEqual(self.rules_of(out[\"turns\"][0]), [\"R-c menu gallery expand\"])\n\n    def test_r_d_shapes_menu_real_foreground_click(self):\n        turn = _turn(1, \"desktop.click\", {\"ref\": \"@e1\"},\n                     target={\"ref\": {\"ref\": \"@e1\", \"role\": \"listitem\", \"name\": \"Rectangle\", \"window_title\": \"Book1\"}})\n        out, _ = self.play([turn], text='@e4 menuitem \"Shapes\"\\n  @e54 listitem \"Rectangle\"')\n        self.assertEqual(self.rules_of(out[\"turns\"][0]), [\"R-d Shapes menu real foreground click\"])\n\n    def test_r_e_excel_selected_cell_set_value(self):\n        turn = _turn(1, \"desktop.type\", {\"window\": \"Book1 - Excel\", \"text\": \"5\"},\n                     target={\"window\": {\"window_title\": \"Book1 - Excel\", \"process\": \"EXCEL.EXE\"}})\n\n        def act(method, params):\n            if method == \"desktop.type\":\n                raise ProtocolError(ErrorCode.INTERNAL, \"foreground_unavailable: the window is behind another\")\n            return {\"effect_state\": \"committed\"}\n\n        def text(params):\n            return 'edit \"Name Box\" value=\"A1\"' if params.get(\"query\") == \"Name Box\" else '@e80 griditem \"A1\" [id=A1]'\n        out, calls = self.play([turn], text=text, act=act)\n        self.assertEqual(out[\"turns\"][0][\"ok\"], True)\n        self.assertEqual(self.rules_of(out[\"turns\"][0]), [\"R-e Excel selected cell set_value\"])\n\n    def test_r_f_click_with_fresh_pixels(self):\n        turn = _turn(1, \"desktop.click\", {\"ref\": \"@e1\"},\n                     target={\"ref\": {\"ref\": \"@e1\", \"role\": \"button\", \"name\": \"Save\", \"window_title\": \"Fixture\"}})\n\n        def act(method, params):\n            if method == \"desktop.click\" and not params.get(\"real\"):\n                raise ProtocolError(ErrorCode.INTERNAL, \"COMError: event was unable to invoke subscribers\")\n            return {\"effect_state\": \"committed\"}\n        out, _ = self.play([turn], text='@e5 button \"Save\"', act=act)\n        self.assertEqual(out[\"turns\"][0][\"ok\"], True)\n        self.assertEqual(self.rules_of(out[\"turns\"][0]), [\"R-f click with fresh pixels\"])\n\n    def _legacy_shape_turns(self):\n        def click(n, role, name):\n            return _turn(n, \"desktop.click\", {\"ref\": \"@e1\"}, target={\"ref\": {\n                \"ref\": \"@e1\", \"role\": role, \"name\": name, \"window_title\": \"Book1 - Excel\", \"process\": \"EXCEL.EXE\"}})\n        return [click(1, \"menuitem\", \"Illustrations\"), _turn(2, \"desktop.drag\", {\"x\": 1}),\n                click(3, \"button\", \"Rectangle 1\")]\n\n    LEGACY_TEXT = ('@e51 menuitem \"Illustrations\"\\n@e4 menuitem \"Shapes\" [id=ShapesInsertGallery]\\n'\n                   '  @e54 listitem \"Rectangle\"\\n@e60 button \"Rectangle 1\"')\n\n    def test_r_g_compatibility_focus(self):\n        out, calls = self.play(self._legacy_shape_turns(), text=self.LEGACY_TEXT)\n        rectangle = [r for r in out[\"turns\"] if r.get(\"inserted\")][1]\n        self.assertIn(\"R-g compatibility focus\", self.rules_of(rectangle))\n        self.assertIn((\"desktop.focus\", {\"window\": \"Book1 - Excel\", \"force_fallback\": True}), calls)\n\n    def test_r_h_legacy_office_gallery_steps_are_marked_inserted(self):\n        out, _ = self.play(self._legacy_shape_turns(), text=self.LEGACY_TEXT)\n        inserted = [r for r in out[\"turns\"] if r.get(\"inserted\")]\n        self.assertEqual(len(inserted), 2)\n        for row in inserted:\n            self.assertEqual(row[\"reason\"], \"legacy Office gallery action\")\n            self.assertIn(\"R-h legacy Office gallery step\", self.rules_of(row))\n        self.assertEqual([r[\"turn\"] for r in out[\"turns\"]], [1, 1, 1, 2, 3])\n        self.assertNotIn(\"inserted\", out[\"turns\"][0])\n\n    def test_r_i_keeps_its_skip_reason(self):\n        turn = _turn(1, \"desktop.open_app\", {\"command\": \"cua-driver.exe\"})\n        out, _ = self.play([turn])\n        self.assertEqual(out[\"turns\"][0], {\"turn\": 1, \"tool\": \"desktop.open_app\", \"skipped\": \"tool cursor overlay\"})\n\n    def test_r_j_search_enter_after_a_typed_newline(self):\n        turn = _turn(1, \"desktop.type\", {\"window\": \"#5\", \"text\": \"notepad\\n\"},\n                     target={\"window\": {\"window_title\": \"Search\"}})\n        out, calls = self.play([turn], windows=[{\"handle\": 7, \"title\": \"Search\"}])\n        self.assertIn(\"R-j Search Enter after a typed newline\", self.rules_of(out[\"turns\"][0]))\n        self.assertIn((\"desktop.key\", {\"keys\": \"enter\", \"window\": \"#7\", \"delivery_mode\": \"background\"}), calls)\n\n    def test_a_value_source_failure_before_the_step_is_a_plain_failed_row(self):\n        turn = {**_turn(1, \"zz.act\", {\"x\": 1}), \"values\": {\"x\": {\"kind\": \"list\", \"items\": []}}}\n        with patch.object(trajectory.values, \"resolve_values\",\n                          side_effect=ProtocolError(ErrorCode.INTERNAL, \"no value for repetition 1\")):\n            out, _ = self.play([turn])\n        self.assertEqual(out[\"turns\"][0], {\"turn\": 1, \"tool\": \"zz.act\", \"ok\": False, \"error\": \"no value for repetition 1\"})\n\n    def test_a_step_no_rule_touches_has_no_rules_key(self):\n        out, _ = self.play([_turn(1, \"zz.act\", {\"x\": 1})])\n        self.assertEqual(out[\"turns\"][0], {\"turn\": 1, \"tool\": \"zz.act\", \"ok\": True,\n                                           \"result_summary\": out[\"turns\"][0][\"result_summary\"]})\n        self.assertNotIn(\"rules\", out[\"turns\"][0])\n\n\nclass TrajectoryRecorderTests(unittest.TestCase):\n    def setUp(self):\n        tmp = tempfile.TemporaryDirectory()\n        self.addCleanup(tmp.cleanup)\n        self.home = Path(tmp.name)\n\n    def test_turns_are_written_like_cua_with_their_arguments_as_given(self):\n        rec = trajectory.Recorder(self.home, \"20261030-170000-abcd\")\n        first = rec.record(tool=\"desktop.type\", arguments={\"ref\": \"@e2\", \"text\": \"hello\", \"password\": \"s3cret\"},\n                           outcome=\"ok\", effect=\"committed\", result={\"effect_state\": \"committed\", \"verified\": True},\n                           elapsed_ms=12, session=\"abcd\", client={\"name\": \"claude-code\"},\n                           target={\"ref\": {\"ref\": \"@e2\", \"role\": \"edit\", \"name\": \"Name\", \"window_title\": \"Form\",\n                                           \"process\": \"app.exe\"}}, read_only=False, delivery=\"background\")\n        rec.record(tool=\"path.list\", arguments={}, outcome=\"ok\", effect=\"none\", result={}, elapsed_ms=1,\n                   session=\"abcd\", read_only=True)\n        folder = self.home / \"runs\" / \"20261030-170000-abcd\"\n        self.assertTrue((folder / \"turn-00001\" / \"action.json\").is_file())\n        self.assertTrue((folder / \"turn-00002\" / \"action.json\").is_file())\n        on_disk = json.loads((folder / \"turn-00001\" / \"action.json\").read_text(encoding=\"utf-8\"))\n        self.assertEqual((on_disk[\"turn\"], on_disk[\"tool\"], on_disk[\"arguments\"][\"text\"]), (1, \"desktop.type\", \"hello\"))\n        # db7 Item H (owner: the saved workflow replays offline with every detail; R53 no privacy limits): as given\n        self.assertEqual(on_disk[\"arguments\"][\"password\"], \"s3cret\")\n        self.assertEqual((on_disk[\"result_error\"], on_disk[\"result_summary\"][\"verified\"]), (False, True))\n        self.assertEqual(on_disk[\"target\"][\"ref\"][\"name\"], \"Name\")\n        self.assertTrue(on_disk[\"timestamp\"].startswith(\"20\"))\n        self.assertEqual(first[\"session\"], \"abcd\")\n        turns = rec.turns()\n        self.assertEqual([t[\"tool\"] for t in turns], [\"desktop.type\", \"path.list\"])\n        self.assertEqual([t[\"read_only\"] for t in turns], [False, True])\n        self.assertEqual(trajectory.load_turns(folder)[1][\"turn\"], 2)\n\n    def test_a_workflow_document_carries_the_run_and_its_turns(self):\n        doc = trajectory.workflow_doc(\"notes\", {\"kind\": \"session\", \"name\": None, \"started\": 1.0, \"sessions\": [\"ab\"]},\n                                      [_turn(1, \"desktop.click\", {\"ref\": \"@e1\"})])\n        self.assertEqual((doc[\"format\"], doc[\"kind\"], doc[\"name\"], len(doc[\"turns\"])), (\"kgrow.flow\", \"run\", \"notes\", 1))\n        self.assertEqual(doc[\"run\"][\"sessions\"], [\"ab\"])\n\n\nclass TrajectoryReplayTests(unittest.TestCase):\n    def test_a_failing_optional_close_carries_on_to_the_next_step(self):\n        close = _turn(1, \"desktop.close_window\", {\"window\": \"zz-no-such-window\"})\n        close[\"optional\"] = True\n        turns = [close, _turn(2, \"zz.next\", {\"value\": \"continued\"})]\n        calls = []\n\n        def delegate(method, params):\n            calls.append((method, dict(params)))\n            if method == \"desktop.close_window\":\n                raise ProtocolError(ErrorCode.WINDOW_NOT_FOUND, \"optional close target is absent\")\n            self.assertEqual(method, \"zz.next\")\n            return {\"effect_state\": \"committed\"}\n\n        out = trajectory.replay(delegate, turns, delay_ms=0)\n        self.assertEqual(calls, [\n            (\"desktop.close_window\", {\"window\": \"zz-no-such-window\"}),\n            (\"zz.next\", {\"value\": \"continued\"}),\n        ])\n        self.assertEqual((out[\"attempted\"], out[\"succeeded\"], out[\"failed\"], out[\"skipped\"]), (2, 1, 1, 0))\n        self.assertTrue(out[\"stop_on_error\"])\n        self.assertNotIn(\"first_failure\", out)\n        self.assertNotIn(\"stopped\", out)\n        self.assertEqual(len(out[\"turns\"]), 2)\n        self.assertEqual(out[\"turns\"][0], {\n            \"turn\": 1, \"tool\": \"desktop.close_window\", \"ok\": False,\n            \"error\": \"optional close target is absent\", \"optional\": True,\n        })\n        self.assertEqual(\n            (out[\"turns\"][1][\"turn\"], out[\"turns\"][1][\"tool\"], out[\"turns\"][1][\"ok\"]),\n            (2, \"zz.next\", True),\n        )\n\n    def test_a_recorded_transient_window_close_that_is_already_gone_does_not_stop_play(self):\n        from autoskill import recorder as rec_mod\n\n        with tempfile.TemporaryDirectory() as tmp:\n            recorder = trajectory.Recorder(Path(tmp), \"20990101-010101-abcd\")\n            assembler = rec_mod.Assembler(recorder)\n            fake_pid = os.getpid() + 1\n            active = {\n                \"assembler\": assembler, \"baseline\": set(), \"launched\": {fake_pid}, \"known\": {},\n                \"poller_windows\": [[(222, fake_pid, \"Opening - Excel\")], []],\n            }\n            human_recorder = rec_mod.HumanRecorder.__new__(rec_mod.HumanRecorder)\n            with patch.object(rec_mod, \"_process_name\", return_value=\"EXCEL.EXE\"):\n                human_recorder._poll_once(active)\n                human_recorder._poll_once(active)\n            recorded = recorder.turns()\n            self.assertEqual(len(recorded), 1)\n            close = recorded[0]\n            self.assertEqual(close[\"tool\"], \"desktop.close_window\")\n            self.assertEqual(close[\"arguments\"], {\"window\": \"#222\"})\n            self.assertEqual(close[\"target\"], {\"window\": {\n                \"handle\": \"#222\", \"window_title\": \"Opening - Excel\", \"process\": \"EXCEL.EXE\",\n            }})\n            self.assertTrue(close[\"optional\"])\n            self.assertFalse(close[\"read_only\"])\n            self.assertNotIn(\"skip\", close)\n            calls = []\n\n            def delegate(method, params):\n                calls.append((method, dict(params)))\n                if method == \"desktop.windows\":\n                    return {\"windows\": []}\n                self.assertEqual(method, \"zz.next\", \"a missing window must fail before close dispatch\")\n                return {\"effect_state\": \"committed\"}\n\n            out = trajectory.replay(\n                delegate, recorded + [_turn(2, \"zz.next\", {\"value\": \"continued\"})], delay_ms=0)\n            self.assertEqual(calls, [\n                (\"desktop.windows\", {}),\n                (\"zz.next\", {\"value\": \"continued\"}),\n            ])\n            self.assertEqual((out[\"attempted\"], out[\"succeeded\"], out[\"failed\"], out[\"skipped\"]), (2, 1, 1, 0))\n            self.assertTrue(out[\"stop_on_error\"])\n            self.assertNotIn(\"first_failure\", out)\n            self.assertNotIn(\"stopped\", out)\n            self.assertEqual(len(out[\"turns\"]), 2)\n            self.assertEqual(out[\"turns\"][0], {\n                \"turn\": 1, \"tool\": \"desktop.close_window\", \"ok\": False, \"optional\": True,\n                \"error\": \"step 1: no window titled 'Opening - Excel' (or one alike) is open now\",\n            })\n            self.assertEqual(\n                (out[\"turns\"][1][\"turn\"], out[\"turns\"][1][\"tool\"], out[\"turns\"][1][\"ok\"]),\n                (2, \"zz.next\", True),\n            )\n            self.assertEqual(close[\"arguments\"], {\"window\": \"#222\"})\n\n    def test_a_missing_element_names_its_kind_and_window_after_the_wait(self):\n        for case in (\"missing\", \"late\", \"wait_other_error\",\n                     \"first_observe_error\", \"second_observe_error\"):\n            with self.subTest(case=case):\n                calls = []\n                state = {\"observes\": 0}\n                wait_error = ProtocolError(\n                    ErrorCode.TIMEOUT, \"no element matching 'Save' appeared within 5s\")\n                observe_error = ProtocolError(ErrorCode.INTERNAL, \"observation failed\")\n                other_error = RuntimeError(\"wait transport crashed\")\n                turn = _turn(7, \"desktop.click\", {\"ref\": \"@e1\"}, target={\"ref\": {\n                    \"ref\": \"@e1\", \"role\": \"button\", \"name\": \"Save\", \"window_title\": \"Fixture\"}})\n\n                def delegate(method, params):\n                    calls.append((method, dict(params)))\n                    if method == \"desktop.observe\":\n                        state[\"observes\"] += 1\n                        if ((case == \"first_observe_error\" and state[\"observes\"] == 1)\n                                or (case == \"second_observe_error\" and state[\"observes\"] == 2)):\n                            raise observe_error\n                        return {\"text\": '@e5 button \"Save\"'\n                                if case == \"late\" and state[\"observes\"] == 2 else \"\"}\n                    if method == \"desktop.wait_ref\":\n                        if case == \"wait_other_error\":\n                            raise other_error\n                        raise wait_error\n                    self.fail(f\"target resolution must not send an action: {method}\")\n\n                if case == \"late\":\n                    self.assertEqual(trajectory.resolve_arguments(delegate, turn), {\"ref\": \"@e5\"})\n                else:\n                    exception_type = RuntimeError if case == \"wait_other_error\" else ProtocolError\n                    with self.assertRaises(exception_type) as caught:\n                        trajectory.resolve_arguments(delegate, turn)\n                    if case == \"missing\":\n                        error = caught.exception.error\n                        self.assertIs(error.code, ErrorCode.TARGET_NOT_FOUND)\n                        self.assertIn(\"no button named 'Save'\", error.message)\n                        self.assertIn(\"window 'Fixture'\", error.message)\n                        self.assertIn(\"The screen differs from the recording\", error.hint or \"\")\n                    else:\n                        self.assertIs(caught.exception,\n                                      other_error if case == \"wait_other_error\" else observe_error)\n\n                observe = (\"desktop.observe\",\n                           {\"window\": \"Fixture\", \"query\": \"Save\", \"screenshot\": False})\n                wait = (\"desktop.wait_ref\", {\"name\": \"Save\", \"window\": \"Fixture\", \"timeout\": 5})\n                expected = [observe]\n                if case != \"first_observe_error\":\n                    expected.append(wait)\n                    if case != \"wait_other_error\":\n                        expected.append(observe)\n                self.assertEqual(calls, expected)\n                self.assertEqual(turn[\"arguments\"], {\"ref\": \"@e1\"})\n\n    def test_a_step_whose_element_appears_late_succeeds_on_its_retry(self):\n        state = {\"observes\": 0}\n        clicks = []\n\n        def delegate(method, params):\n            if method == \"desktop.observe\":\n                state[\"observes\"] += 1\n                return {\"text\": '@e5 button \"Save\"' if state[\"observes\"] >= 3 else \"\"}\n            if method == \"desktop.wait_ref\":\n                raise ProtocolError(ErrorCode.TARGET_NOT_FOUND,\n                                    \"no element matching 'Save' appeared within 5s\")\n            if method == \"desktop.click\":\n                clicks.append(dict(params))\n                return {\"effect_state\": \"committed\"}\n            self.fail(f\"unexpected call: {method}\")\n\n        turn = _turn(1, \"desktop.click\", {\"ref\": \"@e1\"}, target={\"ref\": {\n            \"ref\": \"@e1\", \"role\": \"button\", \"name\": \"Save\", \"window_title\": \"Fixture\"}})\n        turn.update(retries=2, retry_delay_ms=0)\n        out = trajectory.replay(delegate, [turn], delay_ms=0, sleep=lambda _: None)\n        self.assertEqual((out[\"attempted\"], out[\"succeeded\"], out[\"failed\"]), (1, 1, 0))\n        self.assertGreaterEqual(state[\"observes\"], 3)\n        self.assertEqual(clicks, [{\"ref\": \"@e5\"}])\n        self.assertNotIn(\"first_failure\", out)\n\n    def test_a_step_that_never_finds_its_element_fails_after_every_try(self):\n        waits, slept = [], []\n\n        def delegate(method, params):\n            if method == \"desktop.observe\":\n                return {\"text\": \"\"}\n            if method == \"desktop.wait_ref\":\n                waits.append(dict(params))\n                raise ProtocolError(ErrorCode.TARGET_NOT_FOUND,\n                                    \"no element matching 'Save' appeared within 5s\")\n            self.fail(f\"an unresolved step must not act: {method}\")\n\n        turn = _turn(1, \"desktop.click\", {\"ref\": \"@e1\"}, target={\"ref\": {\n            \"ref\": \"@e1\", \"role\": \"button\", \"name\": \"Save\", \"window_title\": \"Fixture\"}})\n        turn.update(retries=2, retry_delay_ms=0)\n        out = trajectory.replay(delegate, [turn], delay_ms=0, sleep=slept.append)\n        self.assertEqual((out[\"attempted\"], out[\"succeeded\"], out[\"failed\"]), (1, 0, 1))\n        self.assertEqual(len(waits), 3)\n        self.assertEqual(slept, [0, 0])\n        self.assertEqual(len(out[\"turns\"]), 1)\n        self.assertIn(\"Save\", out[\"first_failure\"][\"error\"])\n\n    def test_excel_fallback_protocol_errors_consume_the_retry_budget(self):\n        for retries in (0, 2, 10):\n            for transient in (True, False):\n                with self.subTest(retries=retries, transient=transient):\n                    state = {\"types\": 0, \"sets\": 0, \"windows\": 0}\n                    slept = []\n\n                    def delegate(method, params):\n                        if method == \"desktop.windows\":\n                            state[\"windows\"] += 1\n                            return {\"windows\": [{\"handle\": 2, \"title\": \"Book1 - Excel\",\n                                                 \"process\": \"EXCEL.EXE\"}]}\n                        if method == \"desktop.type\":\n                            state[\"types\"] += 1\n                            self.assertEqual(params[\"window\"], \"#2\")\n                            if transient and state[\"types\"] == 3:\n                                return {\"effect_state\": \"committed\"}\n                            raise ProtocolError(ErrorCode.INTERNAL,\n                                                \"foreground_unavailable: no input was sent\")\n                        if method == \"desktop.observe\":\n                            if params.get(\"query\") == \"Name Box\":\n                                return {\"text\": '@e40 combobox \"Name Box\" =\"C2\"'}\n                            return {\"text\": '@e80 griditem \"C2\" [id=C2]'}\n                        if method == \"desktop.set_value\":\n                            state[\"sets\"] += 1\n                            self.assertEqual(params, {\"ref\": \"@e80\", \"value\": \"retry value\",\n                                                      \"delivery_mode\": \"background\"})\n                            raise ProtocolError(ErrorCode.TARGET_NOT_FOUND,\n                                                f\"cell edit failed {state['sets']}\")\n                        self.fail(f\"unexpected call: {method}\")\n\n                    turn = _turn(8, \"desktop.type\", {\"text\": \"retry value\", \"window\": \"#1\",\n                                                    \"delivery_mode\": \"background\"},\n                                 target={\"window\": {\"handle\": \"#1\", \"window_title\": \"Book1 - Excel\",\n                                                    \"process\": \"EXCEL.EXE\"}})\n                    turn.update(retries=retries, retry_delay_ms=250)\n                    out = trajectory.replay(delegate, [turn], delay_ms=0, sleep=slept.append)\n                    success = transient and retries >= 2\n                    attempts = 3 if success else retries + 1\n                    fallback_calls = attempts - int(success)\n                    self.assertEqual((out[\"attempted\"], out[\"succeeded\"], out[\"failed\"]),\n                                     (1, int(success), int(not success)))\n                    self.assertEqual(state, {\"types\": attempts, \"sets\": fallback_calls,\n                                             \"windows\": attempts})\n                    self.assertEqual(slept, [0.25] * (attempts - 1))\n                    if success:\n                        self.assertNotIn(\"first_failure\", out)\n                    else:\n                        self.assertEqual(out[\"first_failure\"][\"error\"],\n                                         f\"cell edit failed {fallback_calls}\")\n\n        # A later resolution failure must not reuse an earlier attempt's arguments.\n        with self.subTest(resolution_lost_after_fallback_failure=True):\n            state = {\"resolves\": 0, \"types\": 0, \"sets\": 0, \"name_boxes\": 0}\n            slept = []\n\n            def delegate(method, params):\n                if method == \"desktop.observe\":\n                    if params.get(\"query\") == \"Cell\":\n                        state[\"resolves\"] += 1\n                        if state[\"sets\"]:\n                            raise ProtocolError(ErrorCode.INTERNAL,\n                                                \"foreground_unavailable: cell cannot be resolved\")\n                        return {\"text\": '@e9 edit \"Cell\"'}\n                    if params.get(\"query\") == \"Name Box\":\n                        state[\"name_boxes\"] += 1\n                        return {\"text\": '@e40 combobox \"Name Box\" =\"C2\"'}\n                    return {\"text\": '@e80 griditem \"C2\" [id=C2]'}\n                if method == \"desktop.type\":\n                    state[\"types\"] += 1\n                    raise ProtocolError(ErrorCode.INTERNAL,\n                                        \"foreground_unavailable: no input was sent\")\n                if method == \"desktop.set_value\":\n                    state[\"sets\"] += 1\n                    raise ProtocolError(ErrorCode.TARGET_NOT_FOUND, \"cell edit failed\")\n                self.fail(f\"unexpected call: {method}\")\n\n            turn = _turn(8, \"desktop.type\",\n                         {\"text\": \"retry value\", \"window\": \"Book1 - Excel\", \"ref\": \"@e1\"},\n                         target={\"ref\": {\"ref\": \"@e1\", \"role\": \"edit\", \"name\": \"Cell\",\n                                         \"window_title\": \"Book1 - Excel\"},\n                                 \"window\": {\"window_title\": \"Book1 - Excel\",\n                                            \"process\": \"EXCEL.EXE\"}})\n            turn.update(retries=2, retry_delay_ms=250)\n            out = trajectory.replay(delegate, [turn], delay_ms=0, sleep=slept.append)\n            self.assertEqual((out[\"succeeded\"], out[\"failed\"]), (0, 1))\n            self.assertEqual(state, {\"resolves\": 3, \"types\": 1, \"sets\": 1, \"name_boxes\": 1})\n            self.assertEqual(slept, [0.25, 0.25])\n            self.assertEqual(out[\"first_failure\"][\"error\"],\n                             \"foreground_unavailable: cell cannot be resolved\")\n\n    def test_pixel_fallback_protocol_errors_consume_the_retry_budget(self):\n        for retries in (0, 2, 10):\n            for transient in (True, False):\n                with self.subTest(retries=retries, transient=transient):\n                    state = {\"primary\": 0, \"pixels\": 0, \"observes\": 0}\n                    slept = []\n\n                    def delegate(method, params):\n                        if method == \"desktop.observe\":\n                            state[\"observes\"] += 1\n                            return {\"text\": f'@e{10 + state[\"observes\"]} button \"Save\"'}\n                        if method == \"desktop.click\":\n                            self.assertEqual(params[\"ref\"], f'@e{10 + state[\"observes\"]}')\n                            if params.get(\"real\"):\n                                state[\"pixels\"] += 1\n                                raise ProtocolError(ErrorCode.TARGET_NOT_FOUND,\n                                                    f\"pixel target failed {state['pixels']}\")\n                            state[\"primary\"] += 1\n                            if transient and state[\"primary\"] == 3:\n                                return {\"effect_state\": \"committed\"}\n                            raise ProtocolError(ErrorCode.INTERNAL,\n                                                \"COMError: event was unable to invoke subscribers\")\n                        self.fail(f\"unexpected call: {method}\")\n\n                    turn = _turn(7, \"desktop.click\", {\"ref\": \"@e1\"}, target={\"ref\": {\n                        \"ref\": \"@e1\", \"role\": \"button\", \"name\": \"Save\", \"window_title\": \"Fixture\"}})\n                    turn.update(retries=retries, retry_delay_ms=250)\n                    out = trajectory.replay(delegate, [turn], delay_ms=0, sleep=slept.append)\n                    success = transient and retries >= 2\n                    attempts = 3 if success else retries + 1\n                    fallback_calls = attempts - int(success)\n                    self.assertEqual((out[\"attempted\"], out[\"succeeded\"], out[\"failed\"]),\n                                     (1, int(success), int(not success)))\n                    self.assertEqual(state, {\"primary\": attempts, \"pixels\": fallback_calls,\n                                             \"observes\": attempts + fallback_calls})\n                    self.assertEqual(slept, [0.25] * (attempts - 1))\n                    if success:\n                        self.assertNotIn(\"first_failure\", out)\n                    else:\n                        self.assertEqual(out[\"first_failure\"][\"error\"],\n                                         f\"pixel target failed {fallback_calls}\")\n\n    def test_turns_replay_in_order_and_reads_are_skipped(self):\n        calls, slept = [], []\n        turns = [_turn(1, \"path.list\", read_only=True), _turn(2, \"zz.a\", {\"x\": 1}), _turn(3, \"zz.b\", {\"y\": 2})]\n        out = trajectory.replay(lambda m, p: calls.append((m, p)) or {\"effect_state\": \"committed\"}, turns,\n                                delay_ms=250, sleep=slept.append)\n        self.assertEqual(calls, [(\"zz.a\", {\"x\": 1}), (\"zz.b\", {\"y\": 2})])\n        self.assertEqual((out[\"attempted\"], out[\"succeeded\"], out[\"failed\"], out[\"skipped\"]), (2, 2, 0, 1))\n        self.assertEqual(slept, [0.25, 0.25])\n        self.assertEqual([t[\"ok\"] for t in out[\"turns\"] if \"ok\" in t], [True, True])\n        self.assertNotIn(\"first_failure\", out)\n\n    def test_stop_on_error_stops_at_the_first_failure_and_best_effort_goes_on(self):\n        def delegate(method, params):\n            if method == \"zz.bad\":\n                raise ProtocolError(ErrorCode.TARGET_NOT_FOUND, \"no such button\")\n            return {\"effect_state\": \"committed\"}\n        turns = [_turn(1, \"zz.ok\"), _turn(2, \"zz.bad\"), _turn(3, \"zz.ok\")]\n        out = trajectory.replay(delegate, turns, delay_ms=0)\n        self.assertEqual((out[\"attempted\"], out[\"succeeded\"], out[\"failed\"]), (2, 1, 1))\n        self.assertEqual(out[\"first_failure\"], {\"turn\": 2, \"tool\": \"zz.bad\", \"error\": \"no such button\"})\n        out = trajectory.replay(delegate, turns, delay_ms=0, stop_on_error=False)\n        self.assertEqual((out[\"attempted\"], out[\"succeeded\"], out[\"failed\"]), (3, 2, 1))\n\n    def test_a_ref_is_found_again_by_its_identity(self):\n        calls = []\n\n        def delegate(method, params):\n            calls.append((method, params))\n            if method == \"desktop.observe\":\n                return {\"text\": 'window \"Book1 - Excel\"\\n  @e7 button \"Cancel\"\\n  @e9 button \"Save\"\\n'}\n            return {\"effect_state\": \"committed\"}\n        turn = _turn(1, \"desktop.click\", {\"ref\": \"@e3\"}, target={\"ref\": {\n            \"ref\": \"@e3\", \"role\": \"button\", \"name\": \"Save\", \"window_title\": \"Book1 - Excel\", \"process\": \"EXCEL.EXE\"}})\n        out = trajectory.replay(delegate, [turn], delay_ms=0)\n        self.assertEqual(calls[0], (\"desktop.observe\", {\"window\": \"Book1 - Excel\", \"query\": \"Save\", \"screenshot\": False}))\n        self.assertEqual(calls[1], (\"desktop.click\", {\"ref\": \"@e9\"}))\n        self.assertEqual(out[\"succeeded\"], 1)\n\n        def nothing(method, params):\n            return {\"text\": 'window \"Book1 - Excel\"\\n  @e7 button \"Cancel\"\\n'}\n        out = trajectory.replay(nothing, [turn], delay_ms=0)\n        self.assertEqual(out[\"failed\"], 1)\n        self.assertIn(\"Save\", out[\"first_failure\"][\"error\"])\n\n    def test_a_late_appearing_control_is_waited_for_once(self):\n        turn = _turn(7, \"desktop.click\", {\"ref\": \"@e1\"}, target={\"ref\": {\n            \"ref\": \"@e1\", \"role\": \"listitem\", \"name\": \"Blank workbook\", \"window_title\": \"Excel\"}})\n        calls = []\n\n        def delegate(method, params):\n            calls.append((method, params))\n            if method == \"desktop.observe\":\n                text = '@e17 listitem \"Blank workbook\"' if len(calls) > 2 else \"\"\n                return {\"text\": text}\n            return {\"effect_state\": \"committed\"}\n\n        out = trajectory.replay(delegate, [turn], delay_ms=0)\n        self.assertEqual(out[\"succeeded\"], 1)\n        self.assertIn(\"desktop.wait_ref\", [m for m, _ in calls])\n\n    def test_a_step_without_a_delivery_mode_keeps_the_tools_default(self):\n        for tool, payload in (\n            (\"desktop.click\", {}),\n            (\"desktop.type\", {\"text\": \"test\"}),\n            (\"desktop.key\", {\"keys\": \"enter\"}),\n        ):\n            with self.subTest(tool=tool):\n                turn = _turn(1, tool, {\"ref\": \"@e1\", **payload}, target={\"ref\": {\n                    \"ref\": \"@e1\", \"role\": \"edit\", \"name\": \"Cell\", \"window_title\": \"Fixture\"}})\n                calls = []\n\n                def delegate(method, params):\n                    calls.append((method, dict(params)))\n                    if method == \"desktop.observe\":\n                        return {\"text\": '@e18 edit \"Cell\"'}\n                    return {\"effect_state\": \"committed\"}\n\n                out = trajectory.replay(delegate, [turn], delay_ms=0)\n                self.assertEqual(out[\"succeeded\"], 1)\n                actions = [(method, params) for method, params in calls if method == tool]\n                self.assertEqual(actions, [(tool, {\"ref\": \"@e18\", **payload})])\n                self.assertNotIn(\"delivery_mode\", actions[0][1])\n                self.assertEqual(turn[\"arguments\"], {\"ref\": \"@e1\", **payload})\n\n    def test_a_recorded_foreground_click_replays_in_the_foreground(self):\n        turn = _turn(7, \"desktop.click\", {\"ref\": \"@e1\", \"delivery_mode\": \"foreground\"},\n                     target={\"ref\": {\"ref\": \"@e1\", \"role\": \"listitem\", \"name\": \"Blank workbook\",\n                                     \"window_title\": \"Excel\"}})\n        calls = []\n\n        def delegate(method, params):\n            calls.append((method, params))\n            if method == \"desktop.observe\":\n                return {\"text\": '@e18 listitem \"Blank workbook\"'}\n            return {\"effect_state\": \"committed\"}\n\n        out = trajectory.replay(delegate, [turn], delay_ms=0)\n        self.assertEqual(out[\"succeeded\"], 1)\n        self.assertEqual(calls[-1][1][\"delivery_mode\"], \"foreground\")\n\n    def test_recorded_foreground_text_and_keys_replay_in_the_foreground(self):\n        turns = []\n        for number, tool in ((8, \"desktop.type\"), (9, \"desktop.key\")):\n            arguments = {\"delivery_mode\": \"foreground\", \"ref\": \"@e1\"}\n            arguments[\"text\" if tool == \"desktop.type\" else \"keys\"] = \"test\"\n            turns.append(_turn(number, tool, arguments, target={\"ref\": {\n                \"ref\": \"@e1\", \"role\": \"edit\", \"name\": \"Cell\", \"window_title\": \"Book1 - Excel\"}}))\n        calls = []\n\n        def delegate(method, params):\n            calls.append((method, params))\n            if method == \"desktop.observe\":\n                return {\"text\": '@e18 edit \"Cell\"'}\n            return {\"effect_state\": \"committed\"}\n\n        out = trajectory.replay(delegate, turns, delay_ms=0)\n        self.assertEqual(out[\"succeeded\"], 2)\n        actions = [params for method, params in calls if method in (\"desktop.type\", \"desktop.key\")]\n        self.assertEqual([params[\"delivery_mode\"] for params in actions], [\"foreground\", \"foreground\"])\n\n    def test_excel_window_typing_uses_the_selected_grid_item_when_foreground_is_locked(self):\n        turn = _turn(8, \"desktop.type\", {\"text\": \"rtrtd\", \"window\": \"#1\", \"delivery_mode\": \"background\"},\n                     target={\"window\": {\"handle\": \"#1\", \"window_title\": \"Book1 - Excel\", \"process\": \"EXCEL.EXE\"}})\n        calls = []\n\n        def delegate(method, params):\n            calls.append((method, params))\n            if method == \"desktop.windows\":\n                return {\"windows\": [{\"handle\": 2, \"title\": \"Book1 - Excel\", \"process\": \"EXCEL.EXE\"}]}\n            if method == \"desktop.observe\":\n                if params.get(\"query\") == \"Name Box\":\n                    return {\"text\": '@e40 combobox \"Name Box\" =\"C2\"'}\n                return {\"text\": '@e80 griditem \"C2\" [id=C2]'}\n            if method == \"desktop.type\" and params.get(\"window\"):\n                raise ProtocolError(ErrorCode.INTERNAL, \"foreground_unavailable: no input was sent\")\n            return {\"effect_state\": \"committed\"}\n\n        out = trajectory.replay(delegate, [turn], delay_ms=0)\n        self.assertEqual(out[\"succeeded\"], 1)\n        self.assertIn((\"desktop.set_value\", {\"ref\": \"@e80\", \"value\": \"rtrtd\",\n                                             \"delivery_mode\": \"background\"}), calls)\n\n    def test_excel_typing_recovery_does_not_rewrite_an_already_landed_value(self):\n        turn = _turn(8, \"desktop.type\", {\"text\": \"rtrtd\", \"window\": \"#1\", \"delivery_mode\": \"background\"},\n                     target={\"window\": {\"handle\": \"#1\", \"window_title\": \"Book1 - Excel\", \"process\": \"EXCEL.EXE\"}})\n        calls = []\n\n        def delegate(method, params):\n            calls.append((method, params))\n            if method == \"desktop.windows\":\n                return {\"windows\": [{\"handle\": 2, \"title\": \"Book1 - Excel\", \"process\": \"EXCEL.EXE\"}]}\n            if method == \"desktop.observe\":\n                if params.get(\"query\") == \"Name Box\":\n                    return {\"text\": '@e40 combobox \"Name Box\" =\"A1\"'}\n                return {\"text\": '@e80 griditem \"A1\" [value=\"rtrtd\" id=A1]'}\n            if method == \"desktop.type\" and params.get(\"window\"):\n                raise ProtocolError(ErrorCode.INTERNAL, \"foreground_unavailable: delivery outcome is unknown\")\n            return {\"effect_state\": \"committed\"}\n\n        out = trajectory.replay(delegate, [turn], delay_ms=0)\n        self.assertEqual(out[\"succeeded\"], 1)\n        self.assertNotIn(\"desktop.set_value\", [method for method, _ in calls])\n\n    def test_a_com_invoke_failure_reobserves_and_clicks_with_fresh_pixels(self):\n        turn = _turn(7, \"desktop.click\", {\"ref\": \"@e1\", \"delivery_mode\": \"background\"},\n                     target={\"ref\": {\"ref\": \"@e1\", \"role\": \"listitem\", \"name\": \"Blank workbook\",\n                                     \"window_title\": \"Excel\"}})\n        calls = []\n\n        def delegate(method, params):\n            calls.append((method, params))\n            if method == \"desktop.observe\":\n                return {\"text\": '@e18 listitem \"Blank workbook\"'}\n            if method == \"desktop.click\" and not params.get(\"real\"):\n                raise ProtocolError(ErrorCode.INTERNAL, \"COMError: event was unable to invoke subscribers\")\n            return {\"effect_state\": \"committed\"}\n\n        out = trajectory.replay(delegate, [turn], delay_ms=0)\n        self.assertEqual(out[\"succeeded\"], 1)\n        self.assertIn((\"desktop.click\", {\"ref\": \"@e18\", \"real\": True,\n                                         \"delivery_mode\": \"background\"}), calls)\n\n    def test_grid_cell_clicks_use_pixels_to_change_selection(self):\n        turn = _turn(9, \"desktop.click\", {\"ref\": \"@e1\", \"delivery_mode\": \"foreground\"},\n                     target={\"ref\": {\"ref\": \"@e1\", \"role\": \"griditem\", \"name\": \"A2\",\n                                     \"window_title\": \"Book1 - Excel\", \"automation_id\": \"A2\"}})\n        calls = []\n\n        def delegate(method, params):\n            calls.append((method, params))\n            if method == \"desktop.observe\":\n                return {\"text\": '@e111 griditem \"A2\" [id=A2]'}\n            return {\"effect_state\": \"committed\"}\n\n        out = trajectory.replay(delegate, [turn], delay_ms=0)\n        self.assertEqual(out[\"succeeded\"], 1)\n        self.assertTrue(calls[-1][1][\"real\"])\n        self.assertEqual(calls[-1][1][\"delivery_mode\"], \"foreground\")\n\n    def test_a_changed_automation_id_falls_back_to_the_one_element_with_the_same_name_and_kind(self):\n        cases = [\n            ('@e9 button \"Save\" [id=new]', \"button\", \"Save\", \"old\", \"\", \"@e9\"),\n            ('@e9 button \"Save\" [class=New]', \"button\", \"Save\", \"\", \"Old\", \"@e9\"),\n            ('@e9 button \"Save\" [id=new class=New]', \"button\", \"Save\", \"old\", \"Old\", \"@e9\"),\n            ('@e4 link \"Save\" [id=new]\\n@e9 button \"Save\" [id=new]',\n             \"button\", \"Save\", \"old\", \"\", \"@e9\"),\n            ('@e9 listitem \"Save\" [id=new]', \"button\", \"Save\", \"old\", \"\", \"@e9\"),\n            ('@e9 button \"Save\" [id=new]', \"\", \"Save\", \"old\", \"\", \"@e9\"),\n            ('@e9 button \"\\u062d\\u0641\\u0638\" [id=new]',\n             \"button\", \"\\u062d\\u0641\\u0638\", \"old\", \"\", \"@e9\"),\n            ('@e9 button \"Save [a].*(b)?\" [id=new]',\n             \"button\", \"Save [a].*(b)?\", \"old\", \"\", \"@e9\"),\n            # The first pass has candidates but cannot recover between their roles.\n            ('@e4 link \"Save\"\\n@e5 edit \"Save\"\\n@e9 button \"Save\" [id=new]',\n             \"button\", \"Save\", \"old\", \"\", \"@e9\"),\n        ]\n        for text, role, name, automation_id, class_name, expected in cases:\n            with self.subTest(text=text, role=role):\n                self.assertEqual(trajectory.find_ref(text, role, name, automation_id, class_name), expected)\n\n    def test_a_changed_automation_id_with_two_same_named_elements_is_not_guessed(self):\n        cases = [\n            ('@e4 button \"Save\" [id=new1]\\n@e9 button \"Save\" [id=new2]', \"button\", \"Save\", \"old\", \"\"),\n            ('@e4 button \"Save\" [class=New1]\\n@e9 button \"Save\" [class=New2]', \"button\", \"Save\", \"\", \"Old\"),\n            ('@e4 link \"Save\" [id=new1]\\n@e9 link \"Save\" [id=new2]', \"button\", \"Save\", \"old\", \"\"),\n            ('@e4 link \"Save\" [id=new1]\\n@e9 edit \"Save\" [id=new2]', \"button\", \"Save\", \"old\", \"\"),\n            ('@e4 button \"Save\" [id=new1]\\n@e9 button \"Save\" [id=new2]', \"\", \"Save\", \"old\", \"\"),\n            ('@e9 button \"save\" [id=new]', \"button\", \"Save\", \"old\", \"\"),\n            ('@e9 button \"STRASSE\" [id=new]', \"button\", \"Stra\\u00dfe\", \"old\", \"\"),\n            ('@e9 button \"Save as\" [id=new]', \"button\", \"Save\", \"old\", \"\"),\n            ('@e9 button [id=new]', \"button\", \"\", \"old\", \"\"),\n            (\"\", \"button\", \"Save\", \"old\", \"\"),\n            (None, \"button\", \"Save\", \"old\", \"\"),\n        ]\n        for text, role, name, automation_id, class_name in cases:\n            with self.subTest(text=text, role=role, name=name):\n                self.assertIsNone(trajectory.find_ref(text, role, name, automation_id, class_name))\n\n    def test_an_exact_id_match_is_preferred_over_a_name_match(self):\n        pairs = [\n            ('@e4 button \"Save\"', '@e9 button \"Save\" [id=old]', \"old\", \"\"),\n            ('@e4 button \"Save\"', '@e9 button \"Save\" [class=Old]', \"\", \"Old\"),\n            ('@e4 button \"Save\"', '@e9 button \"Save\" [id=old class=Old]', \"old\", \"Old\"),\n            ('@e4 button \"Save\" [id=old]', '@e9 button \"Save\" [id=old class=Old]', \"old\", \"Old\"),\n            ('@e4 button \"Save\" [class=Old]', '@e9 button \"Save\" [id=old class=Old]', \"old\", \"Old\"),\n            ('@e4 button \"Save\" [id=old2]', '@e9 button \"Save\" [id=old]', \"old\", \"\"),\n            ('@e4 button \"Save\" [id=old class=Other]', '@e9 button \"Save\" [id=old class=Old]', \"old\", \"Old\"),\n            ('@e4 button \"Save\" [id=aXb]', '@e9 button \"Save\" [id=a.b]', \"a.b\", \"\"),\n        ]\n        for weaker, exact, automation_id, class_name in pairs:\n            for lines in ((weaker, exact), (exact, weaker)):\n                with self.subTest(lines=lines):\n                    self.assertEqual(trajectory.find_ref(\"\\n\".join(lines), \"button\", \"Save\",\n                                                         automation_id, class_name), \"@e9\")\n        compatible = [\n            # No complete metadata: retain order, without a partial-match score.\n            ('@e4 button \"Save\"\\n@e9 button \"Save\" [id=old]', \"button\", \"old\", \"Old\", \"@e4\"),\n            ('@e4 button \"Save\" [id=old]\\n@e9 button \"Save\" [class=Old]', \"button\", \"old\", \"Old\", \"@e4\"),\n            ('@e4 button \"Save\" [id=old]\\n@e9 button \"Save\" [id=old]', \"button\", \"old\", \"\", \"@e4\"),\n            ('@e4 button \"Save\"\\n@e9 button \"Save\" [id=old]', \"button\", \"\", \"\", \"@e4\"),\n            # Recorded role priority and the legacy consistent-role recovery remain.\n            ('@e4 button \"Save\"\\n@e9 link \"Save\" [id=old]', \"button\", \"old\", \"\", \"@e4\"),\n            ('@e4 listitem \"Save\"\\n@e9 listitem \"Save\" [id=old]', \"button\", \"old\", \"\", \"@e9\"),\n            ('@e4 listitem \"Save\"\\n@e9 listitem \"Save\"', \"button\", \"\", \"\", \"@e4\"),\n            ('@e4 link \"Save\" [id=old]\\n@e9 edit \"Save\"', \"button\", \"old\", \"\", None),\n        ]\n        for text, role, automation_id, class_name, expected in compatible:\n            with self.subTest(text=text, role=role, automation_id=automation_id, class_name=class_name):\n                self.assertEqual(trajectory.find_ref(text, role, \"Save\", automation_id, class_name), expected)\n\n    def test_identity_fallback_reaches_resolver_excel_and_pixel_consumers(self):\n        for tool in (\"desktop.drag\", \"rb.click\", \"browser.click\"):\n            with self.subTest(consumer=tool):\n                arguments = {\"ref\": \"@e1\", \"to_ref\": \"@e2\"} if tool == \"desktop.drag\" else {\"ref\": \"@e1\"}\n                identities = {key: {\"role\": \"button\", \"name\": name, \"automation_id\": \"old\",\n                                    \"window_title\": \"Fixture\"}\n                              for key, name in ((\"ref\", \"Save\"), (\"to_ref\", \"Next\")) if key in arguments}\n                turn = _turn(1, tool, arguments, target=identities)\n                calls = []\n\n                def delegate(method, params):\n                    calls.append((method, params))\n                    return {\"text\": '@e9 button \"Save\" [id=new]\\n@e10 button \"Next\" [id=new]'}\n\n                resolved = trajectory.resolve_arguments(delegate, turn)\n                expected = {\"ref\": \"@e9\", \"to_ref\": \"@e10\"} if tool == \"desktop.drag\" else {\"ref\": \"@e9\"}\n                self.assertEqual(resolved, expected)\n                self.assertEqual(turn[\"arguments\"], {\"ref\": \"@e1\", \"to_ref\": \"@e2\"}\n                                 if tool == \"desktop.drag\" else {\"ref\": \"@e1\"})\n                observe = \"desktop.observe\" if tool == \"desktop.drag\" else tool.split(\".\")[0] + \".observe\"\n                self.assertEqual([method for method, _ in calls], [observe] * len(arguments))\n\n        with self.subTest(consumer=\"second observation\"):\n            calls = []\n\n            def second_observation(method, params):\n                calls.append((method, params))\n                if method == \"desktop.wait_ref\":\n                    raise ProtocolError(ErrorCode.TIMEOUT, \"fixture timeout\")\n                return {\"text\": \"\" if len(calls) == 1 else '@e9 button \"Save\" [id=new]'}\n\n            turn = _turn(1, \"desktop.click\", {\"ref\": \"@e1\"}, target={\"ref\": {\n                \"role\": \"button\", \"name\": \"Save\", \"automation_id\": \"old\", \"window_title\": \"Fixture\"}})\n            self.assertEqual(trajectory.resolve_arguments(second_observation, turn), {\"ref\": \"@e9\"})\n            self.assertEqual([method for method, _ in calls], [\"desktop.observe\", \"desktop.wait_ref\", \"desktop.observe\"])\n            self.assertEqual(calls[1][1][\"timeout\"], 5)\n\n        with self.subTest(consumer=\"Excel selected cell\"):\n            calls = []\n\n            def excel(method, params):\n                calls.append((method, params))\n                if method == \"desktop.observe\":\n                    return {\"text\": '@e3 edit \"Name Box\" =\"A2\"' if params[\"query\"] == \"Name Box\"\n                            else '@e9 griditem \"A2\" [id=new] value=\"before\"'}\n                return {\"effect_state\": \"committed\"}\n\n            turn = _turn(1, \"desktop.type\", {\"text\": \"after\"}, target={\"window\": {\n                \"window_title\": \"Book1 - Excel\", \"process\": \"EXCEL.EXE\"}})\n            result = trajectory._excel_selected_cell_set_value(\n                excel, turn, turn[\"arguments\"], ProtocolError(ErrorCode.INTERNAL, \"foreground_unavailable\"))\n            self.assertEqual(result, {\"effect_state\": \"committed\"})\n            self.assertEqual(calls, [\n                (\"desktop.observe\", {\"window\": \"Book1 - Excel\", \"query\": \"Name Box\", \"screenshot\": False}),\n                (\"desktop.observe\", {\"window\": \"Book1 - Excel\", \"query\": \"A2\", \"screenshot\": False}),\n                (\"desktop.set_value\", {\"ref\": \"@e9\", \"value\": \"after\", \"delivery_mode\": \"background\"}),\n            ])\n\n        with self.subTest(consumer=\"fresh pixels\"):\n            calls = []\n\n            def pixels(method, params):\n                calls.append((method, params))\n                if method == \"desktop.observe\":\n                    return {\"text\": '@e9 button \"Save\" [id=new class=New]'}\n                return {\"effect_state\": \"committed\"}\n\n            turn = _turn(1, \"desktop.click\", {\"ref\": \"@e1\"}, target={\"ref\": {\n                \"role\": \"button\", \"name\": \"Save\", \"automation_id\": \"old\", \"class_name\": \"Old\",\n                \"window_title\": \"Fixture\"}})\n            result = trajectory._click_with_fresh_pixels(pixels, turn, ProtocolError(ErrorCode.INTERNAL, \"COMError\"))\n            self.assertEqual(result, {\"effect_state\": \"committed\"})\n            self.assertEqual(calls, [\n                (\"desktop.observe\", {\"window\": \"Fixture\", \"query\": \"Save\", \"screenshot\": False}),\n                (\"desktop.click\", {\"ref\": \"@e9\", \"real\": True, \"delivery_mode\": \"background\"}),\n            ])\n\n    def test_unreported_class_does_not_hide_a_matching_control(self):\n        text = '@e18 listitem \"Blank workbook\"'\n        self.assertEqual(trajectory.find_ref(text, \"listitem\", \"Blank workbook\",\n                                             class_name=\"NetUIListViewItem\"), \"@e18\")\n        self.assertEqual(trajectory.find_ref(\n            '@e18 listitem \"Blank workbook\" [class=OtherClass]',\n            \"listitem\", \"Blank workbook\", class_name=\"NetUIListViewItem\"), \"@e18\")\n\n    def test_a_recorded_gallery_button_matches_live_shape_listitems(self):\n        turn = _turn(20, \"desktop.click\", {\"ref\": \"@e11\", \"delivery_mode\": \"foreground\"},\n                     target={\"ref\": {\"ref\": \"@e11\", \"role\": \"button\", \"name\": \"Rectangle\",\n                                     \"window_title\": \"Book1 - Excel\", \"process\": \"EXCEL.EXE\"}})\n        calls = []\n\n        def delegate(method, params):\n            calls.append((method, params))\n            if method == \"desktop.observe\":\n                return {\"text\": ('@e4 menuitem \"Shapes\"\\n  @e54 listitem \"Rectangle\"\\n'\n                                 '  @e70 listitem \"Rectangle\"')}\n            return {\"effect_state\": \"committed\"}\n\n        out = trajectory.replay(delegate, [turn], delay_ms=0)\n        self.assertEqual(out[\"succeeded\"], 1)\n        self.assertEqual(calls[-1], (\"desktop.click\", {\"ref\": \"@e54\", \"real\": True,\n                                                       \"delivery_mode\": \"foreground\"}))\n\n    def test_role_recovery_does_not_guess_between_different_live_roles(self):\n        text = '@e4 button \"Rectangle\"\\n@e7 listitem \"Rectangle\"'\n        self.assertIsNone(trajectory.find_ref(text, \"edit\", \"Rectangle\"))\n\n    def test_a_recorded_automation_id_selects_the_right_same_named_control(self):\n        text = ('@e4 menuitem \"More Options\" [id=ShapeFillColorPicker_Dropdown]\\n'\n                '@e9 menuitem \"More Options\" [id=OutlineColorPicker_Dropdown]')\n        turn = _turn(1, \"desktop.click\", {\"ref\": \"@e2\"}, target={\"ref\": {\n            \"ref\": \"@e2\", \"role\": \"menuitem\", \"name\": \"More Options\",\n            \"window_title\": \"Book1 - Excel\", \"automation_id\": \"OutlineColorPicker_Dropdown\"}})\n        calls = []\n\n        def delegate(method, params):\n            calls.append((method, params))\n            if method == \"desktop.observe\":\n                return {\"text\": text}\n            return {\"effect_state\": \"committed\"}\n\n        out = trajectory.replay(delegate, [turn], delay_ms=0)\n        self.assertEqual(out[\"succeeded\"], 1)\n        self.assertEqual(calls[-1][1][\"ref\"], \"@e9\")\n\n    def test_a_recorded_ribbon_menu_click_uses_expand(self):\n        turn = _turn(19, \"desktop.click\", {\"ref\": \"@e8\", \"delivery_mode\": \"foreground\"},\n                     target={\"ref\": {\"ref\": \"@e8\", \"role\": \"menuitem\", \"name\": \"Illustrations\",\n                                     \"window_title\": \"Book1 - Excel\", \"class_name\": \"NetUIAnchor\"}})\n        calls = []\n\n        def delegate(method, params):\n            calls.append((method, params))\n            if method == \"desktop.observe\":\n                return {\"text\": '@e51 menuitem \"Illustrations\"'}\n            return {\"effect_state\": \"committed\"}\n\n        out = trajectory.replay(delegate, [turn], delay_ms=0)\n        self.assertEqual(out[\"succeeded\"], 1)\n        self.assertEqual(calls[-1][1][\"action\"], \"expand\")\n        self.assertEqual(calls[-1][1][\"delivery_mode\"], \"foreground\")\n\n    def test_a_legacy_shape_drag_recovers_the_missing_gallery_steps(self):\n        turns = [\n            _turn(19, \"desktop.click\", {\"ref\": \"@e8\"}, target={\"ref\": {\n                \"ref\": \"@e8\", \"role\": \"menuitem\", \"name\": \"Illustrations\", \"window_title\": \"Book1 - Excel\",\n                \"process\": \"EXCEL.EXE\", \"class_name\": \"NetUIAnchor\"}}),\n            _turn(20, \"desktop.drag\", {\"window\": \"#1\", \"from_x\": 282, \"from_y\": 405,\n                                       \"to_x\": 494, \"to_y\": 472}, target={\"window\": {\n                \"handle\": \"#1\", \"window_title\": \"Book1 - Excel\", \"process\": \"EXCEL.EXE\"}}),\n            _turn(21, \"desktop.click\", {\"ref\": \"@e9\"}, target={\"ref\": {\n                \"ref\": \"@e9\", \"role\": \"image\", \"name\": \"Rectangle 1\", \"window_title\": \"Book1 - Excel\"}}),\n        ]\n        calls = []\n        shape_created = False\n\n        def delegate(method, params):\n            nonlocal shape_created\n            calls.append((method, params))\n            if method == \"desktop.windows\":\n                return {\"windows\": [{\"handle\": 2, \"title\": \"Book1 - Excel\", \"process\": \"EXCEL.EXE\"},\n                                    {\"handle\": 3, \"title\": \"Search\", \"process\": \"SearchHost.exe\"}]}\n            if method == \"desktop.observe\":\n                query = params.get(\"query\")\n                text = {\"Illustrations\": '@e51 menuitem \"Illustrations\"',\n                        \"Shapes\": '@e54 menuitem \"Shapes\" [id=ShapesInsertGallery]',\n                        \"Rectangle\": '@e58 listitem \"Rectangle\"'}.get(query, \"\")\n                if query == \"Rectangle 1\" and shape_created:\n                    text = '@e109 image \"Rectangle 1\"'\n                return {\"text\": text}\n            if method == \"desktop.drag\":\n                shape_created = True\n            return {\"effect_state\": \"committed\"}\n\n        out = trajectory.replay(delegate, turns, delay_ms=0)\n        self.assertEqual((out[\"attempted\"], out[\"succeeded\"], out[\"failed\"]), (5, 5, 0))\n        clicks = [params for method, params in calls if method == \"desktop.click\"]\n        self.assertEqual([params[\"ref\"] for params in clicks], [\"@e51\", \"@e54\", \"@e58\", \"@e109\"])\n        self.assertEqual([params.get(\"action\") for params in clicks[:2]], [\"expand\", \"expand\"])\n        self.assertTrue(clicks[2][\"real\"])\n        self.assertEqual(clicks[2][\"delivery_mode\"], \"foreground\")\n        activation = (\"desktop.focus\", {\"window\": \"Book1 - Excel\", \"force_fallback\": True})\n        self.assertIn(activation, calls)\n        self.assertLess(calls.index(activation), calls.index((\"desktop.click\", clicks[2])))\n        dismiss = (\"desktop.key\", {\"keys\": \"escape\", \"scope\": \"desktop\", \"delivery_mode\": \"foreground\"})\n        self.assertIn(dismiss, calls)\n        self.assertLess(calls.index(dismiss), calls.index(activation))\n        rectangle = next(t for t in trajectory._legacy_shape_steps(turns)\n                         if t[\"arguments\"].get(\"ref\") == \"@legacyRectangle\")\n        self.assertEqual((rectangle[\"retries\"], rectangle[\"retry_delay_ms\"]), (3, 500))\n\n    def test_compatibility_focus_waits_for_the_launch_surface_to_disappear(self):\n        turn = {\"compatibility\": \"legacy Office gallery action\", \"arguments\": {\"delivery_mode\": \"foreground\"},\n                \"target\": {\"ref\": {\"process\": \"EXCEL.EXE\", \"window_title\": \"Book1 - Excel\"}}}\n        calls, slept = [], []\n        searches = iter([[{\"handle\": 3, \"title\": \"Search\"}], []])\n\n        def delegate(method, params):\n            calls.append((method, params))\n            if method == \"desktop.windows\":\n                return {\"windows\": next(searches)}\n            return {\"effect_state\": \"committed\"}\n\n        trajectory._activate_compatibility_target(delegate, turn, sleep=slept.append)\n        self.assertEqual(slept, [0.1])\n        self.assertEqual(calls[-1], (\"desktop.focus\", {\"window\": \"Book1 - Excel\", \"force_fallback\": True}))\n\n    def test_replay_skips_cursor_overlay_launches_from_an_existing_recording(self):\n        turns = [_turn(1, \"desktop.open_app\", {\"command\": \"cua-driver.exe\",\n                                               \"wait_title\": \"Cua.AgentCursorOverlay.default\"}),\n                 _turn(2, \"zz.act\")]\n        calls = []\n        out = trajectory.replay(lambda m, p: calls.append((m, p)) or {\"effect_state\": \"committed\"}, turns, delay_ms=0)\n        self.assertEqual([m for m, _ in calls], [\"zz.act\"])\n        self.assertEqual((out[\"succeeded\"], out[\"skipped\"]), (1, 1))\n\n    def test_a_missing_search_window_is_opened_once_before_typing(self):\n        calls = []\n\n        def delegate(method, params):\n            calls.append((method, params))\n            if method == \"desktop.windows\":\n                return {\"windows\": []} if len(calls) < 3 else {\n                    \"windows\": [{\"handle\": 65984, \"title\": \"Start\", \"process\": \"StartMenuExperienceHost.exe\"}]}\n            return {\"effect_state\": \"committed\"}\n\n        handle = trajectory._window_again(delegate, {\"window_title\": \"Search\"}, {\"turn\": 3})\n        self.assertEqual(handle, \"#65984\")\n        self.assertEqual([m for m, _ in calls], [\"desktop.windows\", \"desktop.key\", \"desktop.wait_window\", \"desktop.windows\"])\n        self.assertEqual(calls[1][1][\"delivery_mode\"], \"foreground\")\n        self.assertEqual(calls[1][1][\"scope\"], \"desktop\")\n        self.assertEqual(calls[2][1][\"window\"], \"Start\")\n        self.assertNotIn(\"timeout\", calls[2][1])\n\n    def test_an_existing_start_window_is_used_without_toggling_it_closed(self):\n        calls = []\n\n        def delegate(method, params):\n            calls.append((method, params))\n            return {\"windows\": [{\"handle\": 65984, \"title\": \"Start\", \"process\": \"StartMenuExperienceHost.exe\"}]}\n\n        handle = trajectory._window_again(delegate, {\"window_title\": \"Search\"}, {\"turn\": 3})\n        self.assertEqual(handle, \"#65984\")\n        self.assertEqual([m for m, _ in calls], [\"desktop.windows\"])\n\n    def test_typing_into_start_uses_background_delivery(self):\n        turn = _turn(3, \"desktop.type\", {\"text\": \"excel\", \"window\": \"#197062\", \"delivery_mode\": \"foreground\"},\n                     target={\"window\": {\"handle\": \"#197062\", \"window_title\": \"Search\", \"process\": \"SearchHost.exe\"}})\n\n        def delegate(method, params):\n            return {\"windows\": [{\"handle\": 65984, \"title\": \"Start\", \"process\": \"StartMenuExperienceHost.exe\"}]}\n\n        arguments = trajectory.resolve_arguments(delegate, turn)\n        self.assertEqual(arguments[\"window\"], \"#65984\")\n        self.assertEqual(arguments[\"delivery_mode\"], \"background\")\n\n    def test_a_trailing_newline_in_search_submits_with_enter(self):\n        turn = _turn(3, \"desktop.type\", {\"text\": \"excel\\n\", \"window\": \"#197062\"},\n                     target={\"window\": {\"handle\": \"#197062\", \"window_title\": \"Search\", \"process\": \"SearchHost.exe\"}})\n        calls = []\n\n        def delegate(method, params):\n            calls.append((method, params))\n            return {\"windows\": [{\"handle\": 65984, \"title\": \"Start\", \"process\": \"StartMenuExperienceHost.exe\"}]}\n\n        out = trajectory.replay(delegate, [turn], delay_ms=0)\n        self.assertEqual(out[\"succeeded\"], 1)\n        self.assertEqual(calls[-1], (\"desktop.key\", {\"keys\": \"enter\", \"window\": \"#65984\",\n                                                     \"delivery_mode\": \"background\"}))\n\n    def test_a_key_into_start_uses_background_delivery(self):\n        turn = _turn(4, \"desktop.key\", {\"keys\": \"alt\", \"window\": \"#197062\", \"delivery_mode\": \"foreground\"},\n                     target={\"window\": {\"handle\": \"#197062\", \"window_title\": \"Search\", \"process\": \"SearchHost.exe\"}})\n\n        def delegate(method, params):\n            return {\"windows\": [{\"handle\": 65984, \"title\": \"Start\", \"process\": \"StartMenuExperienceHost.exe\"}]}\n\n        arguments = trajectory.resolve_arguments(delegate, turn)\n        self.assertEqual(arguments[\"delivery_mode\"], \"background\")\n\n    def test_a_stopped_owner_ends_the_replay(self):\n        turns = [_turn(1, \"zz.a\"), _turn(2, \"zz.b\")]\n        out = trajectory.replay(lambda m, p: {\"effect_state\": \"committed\"}, turns, delay_ms=0, stopped=lambda: True)\n        self.assertEqual((out[\"attempted\"], out.get(\"stopped\")), (0, \"the owner pressed Stop\"))\n\n\nclass _DaemonCase(unittest.TestCase):\n    mode = PermissionMode.FULL\n\n    def setUp(self):\n        tmp = tempfile.TemporaryDirectory()\n        self.addCleanup(tmp.cleanup)\n        self.home = Path(tmp.name)\n        save_policy(self.home, PermissionPolicy(mode=self.mode))\n        self.d = Daemon(self.home)\n        self.addCleanup(self.d.shutdown)\n        self.d.policy.confirm_timeout_s = 1\n\n    def call(self, method, params=None, session=None):\n        return self.d.handle(Request(method=method, params=params or {}, id=\"t\", session=session))\n\n    def start(self, client=None):\n        return self.call(\"session.start\", {\"client\": client} if client else {}).result[\"session_id\"]\n\n\nclass RecorderThroughTheDaemonTests(_DaemonCase):\n    def test_every_step_of_a_run_is_recorded_with_its_ref_identity(self):\n        from autoskill.desktop.refs import RefStore\n        self.d.register(\"desktop.click\", lambda s, p: {\"effect_state\": \"committed\", \"verified\": False})\n        sid = self.start({\"name\": \"claude-code\", \"version\": \"2.1\"})\n        store = self.d.sessions[sid].ref_store\n        store.begin_observation()\n        ref = store.add(None, role=\"button\", name=\"Save\", element_token=\"s00000001:4\", window_pid=100,\n                        top_window=77, process=\"EXCEL.EXE\", window_title=\"Book1 - Excel\", rect=(1, 1, 9, 9))\n        self.assertTrue(self.call(\"desktop.click\", {\"ref\": ref}, session=sid).ok)\n        self.assertTrue(self.call(\"path.list\", session=sid).ok)\n        state = self.call(\"_run.state\").result\n        folder = self.home / \"runs\" / state[\"run_id\"]\n        turns = trajectory.load_turns(folder)\n        self.assertEqual([t[\"tool\"] for t in turns], [\"desktop.click\", \"path.list\"])\n        click = turns[0]\n        self.assertEqual(click[\"arguments\"], {\"ref\": ref})\n        self.assertEqual(click[\"target\"][\"ref\"], {\"ref\": ref, \"role\": \"button\", \"name\": \"Save\",\n                                                  \"window_title\": \"Book1 - Excel\", \"process\": \"EXCEL.EXE\"})\n        self.assertEqual((click[\"session\"], click[\"client\"][\"name\"], click[\"read_only\"]), (sid, \"claude-code\", False))\n        self.assertEqual((click[\"outcome\"], click[\"effect\"]), (\"ok\", \"committed\"))\n        self.assertTrue(turns[1][\"read_only\"])\n        self.assertEqual(state[\"turns\"], 2)\n        # control frames and the session's own start are not steps of the workflow\n        self.assertNotIn(\"session.start\", [t[\"tool\"] for t in turns])\n\n    def test_a_failed_step_is_recorded_as_an_error(self):\n        def bad(s, p):\n            raise ProtocolError(ErrorCode.TARGET_NOT_FOUND, \"gone\")\n        self.d.register(\"desktop.click\", bad)\n        sid = self.start()\n        self.assertFalse(self.call(\"desktop.click\", {\"ref\": \"@e1\"}, session=sid).ok)\n        turns = trajectory.load_turns(self.home / \"runs\" / self.call(\"_run.state\").result[\"run_id\"])\n        self.assertEqual((turns[0][\"outcome\"], turns[0][\"result_error\"], turns[0][\"error\"]),\n                         (\"error\", True, \"target_not_found\"))\n\n\nclass ControllerTests(_DaemonCase):\n    def test_stop_ends_everything_and_keeps_the_hold_until_resume(self):\n        sid = self.start()\n        sleeper = subprocess.Popen([sys.executable, \"-c\", \"import time; time.sleep(60)\"])\n        self.addCleanup(lambda: sleeper.poll() is None and sleeper.kill())\n        self.d.run_control.add_flow(sleeper.pid, \"queue\", \"log\", \"journal\")\n        self.d.register(\"zz.step\", lambda s, p: {\"effect_state\": \"committed\"})\n        self.assertTrue(self.call(\"zz.step\", session=sid).ok)\n        out = self.call(\"_run.stop\")\n        self.assertTrue(out.ok, out.error)\n        self.assertEqual((out.result[\"flows_ended\"], out.result[\"sessions_closed\"]), ([sleeper.pid], [sid]))\n        self.assertIsNotNone(sleeper.wait(10))\n        self.assertEqual(self.d.sessions, {})\n        state = self.call(\"_run.state\").result\n        self.assertEqual(state[\"state\"], \"stopped\")\n        self.assertIsNone(state[\"run\"])\n        self.assertEqual(state[\"last_run\"][\"stopped\"], True)              # kept for Save and Export\n        self.assertTrue(any(r[\"kind\"] == \"request\" for r in state[\"feed\"]))  # the feed stays until Clean\n        self.assertFalse(self.call(\"session.start\").ok)                     # the hold: nothing restarts\n        self.assertTrue(self.call(\"_run.resume\").ok)\n        self.assertTrue(self.call(\"session.start\").ok)\n\n    def test_clean_waits_for_stop_or_the_end_of_the_run_then_clears(self):\n        sid = self.start()\n        refused = self.call(\"_run.clean\")\n        self.assertFalse(refused.ok)\n        self.assertIn(\"after Stop\", refused.error[\"message\"])\n        self.call(\"_run.repeat\", {\"count\": 5})\n        self.call(\"_run.stop\")\n        out = self.call(\"_run.clean\")\n        self.assertTrue(out.ok, out.error)\n        state = self.call(\"_run.state\").result\n        self.assertEqual((state[\"state\"], state[\"run\"], state[\"last_run\"], state[\"repeat\"], state[\"always_allow\"]),\n                         (\"running\", None, None, 1, False))\n        self.assertEqual([r[\"kind\"] for r in state[\"feed\"]], [\"clean\"])\n        self.assertNotIn(sid, self.d.sessions)\n        # a run that ended by itself can be cleaned without Stop\n        sid = self.start()\n        self.call(\"session.stop\", {\"session_id\": sid})\n        self.assertIsNone(self.call(\"_run.state\").result[\"run\"])\n        self.assertTrue(self.call(\"_run.clean\").ok)\n        self.assertTrue(self.call(\"_run.reset\").ok)                         # the old name does the same\n\n    def test_the_agent_hears_the_owners_buttons_on_its_next_reply(self):\n        self.d.register(\"zz.step\", lambda s, p: {\"effect_state\": \"committed\"})\n        a = self.start()\n        self.call(\"_run.pause\")\n        self.call(\"_run.resume\")\n        b = self.start()                                                    # started after the presses\n        self.call(\"_run.note\", {\"action\": \"watchdog\", \"state\": \"started\"})\n        first = self.call(\"zz.step\", session=a).result\n        self.assertEqual([c[\"action\"] for c in first[\"owner_controls\"]], [\"pause\", \"resume\", \"watchdog\"])\n        self.assertEqual(first[\"owner_controls\"][2][\"state\"], \"started\")\n        self.assertNotIn(\"owner_controls\", self.call(\"zz.step\", session=a).result)\n        self.assertEqual([c[\"action\"] for c in self.call(\"zz.step\", session=b).result[\"owner_controls\"]], [\"watchdog\"])\n        self.assertFalse(self.call(\"_run.note\", {\"action\": \"stop\"}).ok)     # only the dashboard's own notes\n\n    def test_the_state_names_the_agents_and_their_sessions(self):\n        a = self.start({\"name\": \"claude-code\", \"version\": \"2.1.302\", \"pid\": 4242})\n        b = self.start()\n        state = self.call(\"_run.state\").result\n        agents = {s[\"session_id\"]: s for s in state[\"agents\"]}\n        self.assertEqual(agents[a][\"client\"], {\"name\": \"claude-code\", \"version\": \"2.1.302\", \"pid\": 4242})\n        self.assertEqual(agents[b][\"client\"], {})\n        self.assertTrue(state[\"run_id\"])\n        self.assertEqual(self.call(\"session.list\").result[\"sessions\"][0].get(\"client\", {}).get(\"name\") in\n                         (\"claude-code\", None), True)\n\n\nclass ControlFramesInGuardedModeTests(_DaemonCase):\n    \"\"\"Live db1 found _run.clean asking for an approval: a control frame not in\n    VERB_RISK takes the DESTRUCTIVE default (M123). Every registered _run.*\n    frame must be a READ, so the owner's buttons never ask the owner.\"\"\"\n    mode = PermissionMode.STRICT\n\n    def test_every_run_control_frame_is_a_read_and_never_gated(self):\n        from autoskill.safety.permissions import VERB_RISK, Risk\n        frames = sorted(m for m in self.d._handlers if m.startswith(\"_run.\"))\n        self.assertTrue(frames)\n        self.assertEqual([m for m in frames if VERB_RISK.get(m) is not Risk.READ], [])\n        for method in (\"_run.state\", \"_run.clean\", \"_run.note\"):\n            params = {\"action\": \"watchdog\", \"state\": \"stopped\"} if method == \"_run.note\" else {}\n            self.assertTrue(self.call(method, params).ok, method)\n        self.assertEqual(self.d.confirmations.pending(), [])\n\n    def test_a_refusal_before_the_action_is_still_noted_without_a_reporting_error(self):\n        # Live db1: a confirmation declined before `identity` was set raised\n        # UnboundLocalError inside the failure reporting (secondary_failure).\n        self.d.register(\"zz.step\", lambda s, p: {\"effect_state\": \"committed\"})\n        self.d.policy.confirm_timeout_s = 0.2\n        sid = self.start()\n        out = self.call(\"zz.step\", session=sid)\n        self.assertFalse(out.ok)\n        self.assertEqual(out.error[\"code\"], \"confirmation_declined\")\n        self.assertNotIn(\"secondary_failure\", out.error.get(\"details\") or {})\n        rows = [r for r in self.call(\"_run.state\").result[\"feed\"] if r[\"kind\"] == \"request\"]\n        self.assertEqual(rows[-1][\"method\"], \"zz.step\")\n        self.assertEqual(rows[-1][\"outcome\"], \"error\")\n\n\nclass SaveToMemoryTests(_DaemonCase):\n    def _run_with_steps(self):\n        self.d.register(\"zz.act\", lambda s, p: {\"effect_state\": \"committed\"})\n        sid = self.start()\n        self.call(\"path.list\", session=sid)\n        self.call(\"zz.act\", {\"n\": 1}, session=sid)\n        self.call(\"zz.act\", {\"n\": 2}, session=sid)\n        return sid\n\n    def test_save_by_name_stores_a_run_the_owner_can_list_show_and_replay(self):\n        sid = self._run_with_steps()\n        out = self.call(\"_run.save\", {\"name\": \"two steps\"})\n        self.assertTrue(out.ok, out.error)\n        self.assertEqual((out.result[\"kind\"], out.result[\"name\"], out.result[\"replayable\"]), (\"run\", \"two steps\", True))\n        stored = self.home / \"workflows\" / \"two steps.kgrow.json\"\n        self.assertTrue(stored.is_file())\n        self.assertEqual(json.loads(stored.read_text(encoding=\"utf-8\"))[\"kind\"], \"run\")\n        self.assertFalse(self.call(\"_run.save\", {\"name\": \"two steps\"}).ok)   # never overwritten\n        rows = self.call(\"path.list\").result[\"paths\"]\n        self.assertIn((\"two steps\", \"run\", 2), [(r[\"name\"], r[\"kind\"], r.get(\"steps\")) for r in rows])\n        shown = self.call(\"path.show\", {\"name\": \"two steps\"}).result\n        self.assertEqual([t[\"tool\"] for t in shown[\"turns\"]], [\"path.list\", \"zz.act\", \"zz.act\"])\n        self.call(\"session.stop\", {\"session_id\": sid})\n        calls = []\n        self.d.register(\"zz.act\", lambda s, p: calls.append(dict(p)) or {\"effect_state\": \"committed\"})\n        self.call(\"_run.repeat\", {\"count\": 2})\n        out = self.call(\"path.run\", {\"name\": \"two steps\"})\n        self.assertTrue(out.ok, out.error)\n        self.assertEqual(calls, [{\"n\": 1}, {\"n\": 2}, {\"n\": 1}, {\"n\": 2}])\n        self.assertEqual((out.result[\"repeat\"], out.result[\"repetitions_done\"]), (2, 2))\n        self.assertEqual((out.result[\"attempted\"], out.result[\"succeeded\"], out.result[\"skipped\"]), (2, 2, 1))\n        self.assertEqual(self.d.sessions, {})                               # the replay's own session is gone\n        state = self.call(\"_run.state\").result\n        self.assertIsNone(state[\"run\"])                                      # the replay ended, so Clean is available\n        self.assertIsNotNone(state[\"last_run\"])\n\n    def test_a_saved_run_replays_with_its_own_delay_and_stops_on_the_first_error(self):\n        self._run_with_steps()\n        self.call(\"_run.save\", {\"name\": \"fragile\"})\n\n        def bad(s, p):\n            raise ProtocolError(ErrorCode.TARGET_NOT_FOUND, \"no such thing\")\n        self.d.register(\"zz.act\", bad)\n        out = self.call(\"path.run\", {\"name\": \"fragile\"})\n        self.assertFalse(out.ok)\n        self.assertIn(\"no such thing\", out.error[\"message\"])\n        self.assertEqual(out.error[\"details\"][\"first_failure\"][\"turn\"], 2)\n\n    def test_save_still_writes_a_file_when_a_file_is_given(self):\n        self._run_with_steps()\n        out = self.call(\"_run.save\", {\"file\": str(self.home / \"out\" / \"copy.kgrow.json\")})\n        self.assertTrue(out.ok, out.error)\n        self.assertEqual(out.result[\"kind\"], \"run\")\n        from autoskill import flowfiles\n        imported = flowfiles.import_file(self.d, Path(out.result[\"saved\"]))\n        self.assertEqual((imported[\"imported\"], imported[\"run_with\"]), (\"run\", \"#path copy\"))\n\n\nclass McpClientIdentityTests(unittest.TestCase):\n    def test_the_client_of_the_mcp_connection_reaches_the_session(self):\n        from autoskill import mcp_server\n        seen = {}\n\n        def fake_call(method, params=None, **kw):\n            seen.update(method=method, params=dict(params or {}))\n            return {\"ok\": True, \"result\": {\"session_id\": \"mcps\"}}\n        server = mcp_server.McpServer(home=Path(tempfile.mkdtemp()))\n        sent = []\n        server._send = lambda msg: sent.append(msg)\n        server.handle({\"jsonrpc\": \"2.0\", \"id\": 1, \"method\": \"initialize\",\n                       \"params\": {\"protocolVersion\": \"2025-06-18\", \"capabilities\": {},\n                                  \"clientInfo\": {\"name\": \"claude-code\", \"version\": \"2.1.302\"}}})\n        self.assertEqual(server.session.client[\"name\"], \"claude-code\")\n        with patch(\"autoskill.client.call\", fake_call):\n            self.assertEqual(server.session.id(), \"mcps\")\n        self.assertEqual(seen[\"method\"], \"session.start\")\n        self.assertEqual((seen[\"params\"][\"client\"][\"name\"], seen[\"params\"][\"client\"][\"pid\"]), (\"claude-code\", os.getpid()))\n\n\nclass CliTests(unittest.TestCase):\n    def _run(self, argv):\n        from autoskill import cli\n        seen = []\n\n        def fake_call(method, params=None, **kw):\n            seen.append((method, dict(params or {})))\n            return {\"ok\": True, \"result\": {\"state\": \"running\", \"session_id\": \"ab\", \"permission_mode\": \"full\"}}\n        with patch(\"autoskill.cli.call\", fake_call), patch(\"sys.stdout\"):\n            cli.main(argv)\n        return seen\n\n    def test_run_clean_and_save_and_the_cli_names_itself(self):\n        self.assertEqual(self._run([\"run\", \"clean\"])[0], (\"_run.clean\", {}))\n        self.assertEqual(self._run([\"run\", \"save\", \"my flow\"])[0], (\"_run.save\", {\"name\": \"my flow\"}))\n        method, params = self._run([\"session\", \"start\"])[0]\n        self.assertEqual((method, params[\"client\"][\"name\"], params[\"client\"][\"pid\"]), (\"session.start\", \"cli\", os.getpid()))\n\n    def test_path_show_renders_a_saved_run(self):\n        from autoskill import cli\n        with patch(\"sys.stdout\") as out:\n            cli._r_path_show({\"name\": \"wrkfiles\", \"kind\": \"run\", \"site\": None,\n                              \"turns\": [{\"tool\": \"desktop.click\", \"arguments\": {\"ref\": \"@e1\"}}]})\n        self.assertIn(\"desktop.click\", str(out.write.call_args_list))\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n");
